var P = [];
P.push("<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">");
P.push("<title>KQuality - Team Dashboard</title>");
P.push("<link rel=\"icon\" type=\"image/jpeg\" href=\"data:image/jpeg;base64,\">");
P.push("<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>");
P.push("<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">");
P.push("<style>");
P.push(":root{");
P.push("  --navy-950:#0A1230; --navy-900:#101B3D; --navy-800:#16225A; --navy-700:#1D2E70;");
P.push("  --blue-600:#2F6FEB; --blue-500:#3B82F6; --blue-100:#DCE9FE;");
P.push("  --sky-500:#0EA5C4; --sky-400:#38BDF8; --teal-600:#0D9488; --teal-500:#14B8A6; --teal-100:#CCFBF1;");
P.push("  --green-600:#4D7C0F; --green-500:#65A30D; --green-100:#ECFCCB;");
P.push("  --amber-600:#B45309; --amber-500:#D97706; --amber-100:#FEF3C7;");
P.push("  --red-600:#B91C1C; --red-500:#DC2626; --red-100:#FEE2E2;");
P.push("  --indigo-600:#4338CA; --indigo-100:#E0E7FF;");
P.push("  --slate-50:#F7F9FC; --slate-100:#EEF1F6; --slate-200:#E3E8F0; --slate-300:#CBD4E1;");
P.push("  --slate-400:#94A3B8; --slate-500:#64748B; --slate-600:#475569; --slate-700:#334155; --slate-900:#0F1729;");
P.push("  --white:#FFFFFF;");
P.push("  --grad-brand:linear-gradient(135deg,var(--navy-800) 0%,var(--blue-600) 60%,var(--teal-500) 100%);");
P.push("  --grad-sidebar:linear-gradient(190deg,var(--navy-950) 0%,var(--navy-900) 55%,var(--navy-800) 100%);");
P.push("  --shadow-sm:0 1px 2px rgba(15,23,41,.06);");
P.push("  --shadow-md:0 2px 10px rgba(15,23,41,.06),0 1px 2px rgba(15,23,41,.04);");
P.push("  --shadow-lg:0 12px 32px rgba(15,23,41,.10),0 2px 6px rgba(15,23,41,.05);");
P.push("  --shadow-glow:0 0 0 3px rgba(47,111,235,.14);");
P.push("  --radius-sm:8px; --radius-md:12px; --radius-lg:16px;");
P.push("  --ease:cubic-bezier(.22,1,.36,1);");
P.push("  --font-ui:'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;");
P.push("  --font-mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;");
P.push("}");
P.push("*,*::before,*::after{box-sizing:border-box}");
P.push("@media (prefers-reduced-motion: reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}");
P.push("body{margin:0;font-family:var(--font-ui);background:var(--slate-50);color:var(--slate-900);font-size:14px;-webkit-font-smoothing:antialiased}");
P.push(":focus-visible{outline:2px solid var(--blue-500);outline-offset:2px;border-radius:4px}");
P.push("a{color:var(--blue-600);text-decoration:none}");
P.push("a:hover{text-decoration:underline}");
P.push("h1{font-size:20px;font-weight:800;letter-spacing:-.01em;margin:0 0 3px}");
P.push("::-webkit-scrollbar{width:10px;height:10px}");
P.push("::-webkit-scrollbar-thumb{background:var(--slate-300);border-radius:8px;border:2px solid var(--slate-50)}");
P.push("::-webkit-scrollbar-track{background:transparent}");
P.push("");
P.push("/* ---------- shell ---------- */");
P.push("#appWrap{min-height:100vh}");
P.push(".sidebar{position:fixed;top:0;left:0;bottom:0;width:250px;background:var(--grad-sidebar);display:flex;flex-direction:column;z-index:40;box-shadow:var(--shadow-lg)}");
P.push(".sidebar__brand{display:flex;align-items:center;gap:10px;padding:20px 18px 16px}");
P.push(".sidebar__mark{width:38px;height:38px;border-radius:11px;background:#fff;flex:none;display:flex;align-items:center;justify-content:center;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.25)}");
P.push(".sidebar__mark img{width:32px;height:32px;object-fit:cover;border-radius:8px}");
P.push(".sidebar__brandtext{font-weight:800;font-size:15.5px;color:#fff;letter-spacing:-.01em;line-height:1.15}");
P.push(".sidebar__brandtext span{display:block;font-weight:500;font-size:10.5px;color:#8FB4F5;letter-spacing:.06em;text-transform:uppercase;margin-top:1px}");
P.push(".sidebar__nav{display:flex;flex-direction:column;gap:2px;padding:10px 12px;flex:1}");
P.push(".tabs{display:contents}");
P.push(".tab{display:flex;align-items:center;gap:10px;text-align:left;padding:10px 12px;border-radius:10px;border:none;background:transparent;color:#AAB8DC;font:inherit;font-weight:600;font-size:13.5px;cursor:pointer;position:relative;transition:background .18s var(--ease),color .18s var(--ease)}");
P.push(".tab svg{flex:none;opacity:.85}");
P.push(".tab:hover{background:rgba(255,255,255,.06);color:#fff}");
P.push(".tab.active{background:linear-gradient(135deg,rgba(47,111,235,.35),rgba(20,184,166,.22));color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}");
P.push(".tab.active svg{opacity:1}");
P.push("#opsBadge{margin-left:auto;font-size:10px;font-weight:700;background:var(--red-500);color:#fff;border-radius:999px;padding:1px 6px;min-width:16px;text-align:center;line-height:1.5}");
P.push("#opsBadge:empty{display:none}");
P.push(".sidebar__foot{padding:12px;border-top:1px solid rgba(255,255,255,.08)}");
P.push("#outBtn{width:100%;display:flex;align-items:center;justify-content:center;gap:8px;font-size:12.5px;font-weight:600;padding:9px 12px;border-radius:10px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04);color:#C7D2E8;cursor:pointer;font-family:inherit;transition:all .18s var(--ease)}");
P.push("#outBtn:hover{color:#fff;border-color:rgba(255,255,255,.3);background:rgba(255,255,255,.08)}");
P.push("");
P.push(".main{margin-left:250px;min-height:100vh;display:flex;flex-direction:column}");
P.push(".wrap{padding:24px 28px 64px;max-width:1300px;width:100%;margin:0 auto}");
P.push(".pagehead{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:18px;flex-wrap:wrap}");
P.push(".sub{color:var(--slate-500);font-size:12.5px;margin-bottom:0}");
P.push("");
P.push("@media (max-width:900px){");
P.push("  .sidebar{position:sticky;flex-direction:row;align-items:center;width:100%;height:auto;bottom:auto;padding:0;overflow-x:auto}");
P.push("  .sidebar__brand{padding:10px 12px}");
P.push("  .sidebar__nav{flex-direction:row;flex:none;padding:6px}");
P.push("  .tab{padding:8px 12px;font-size:12.5px;white-space:nowrap}");
P.push("  .sidebar__foot{border-top:none;padding:6px 10px 6px 0}");
P.push("  #outBtn{width:auto;padding:8px 12px}");
P.push("  .main{margin-left:0}");
P.push("  .wrap{padding:16px 14px 48px}");
P.push("}");
P.push("");
P.push("/* ---------- stat cards ---------- */");
P.push(".stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-bottom:16px}");
P.push(".stat{position:relative;background:var(--white);border:1px solid var(--slate-200);border-radius:var(--radius-md);padding:13px 14px;overflow:hidden;box-shadow:var(--shadow-sm);transition:transform .18s var(--ease),box-shadow .18s var(--ease)}");
P.push(".stat::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--grad-brand)}");
P.push(".stat:hover{transform:translateY(-2px);box-shadow:var(--shadow-md)}");
P.push(".stat .n{font-family:var(--font-mono);font-size:22px;font-weight:600;letter-spacing:-.01em;font-variant-numeric:tabular-nums}");
P.push(".stat .l{font-size:10.5px;color:var(--slate-500);text-transform:uppercase;letter-spacing:.06em;font-weight:700;margin-top:2px}");
P.push("");
P.push("/* ---------- controls ---------- */");
P.push(".controls{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px;align-items:center}");
P.push("input[type=search],select,.modal input,.modal textarea,.modal select{padding:9px 12px;border:1px solid var(--slate-200);border-radius:var(--radius-sm);font-size:13px;background:var(--white);font-family:inherit;color:var(--slate-900);transition:border-color .15s,box-shadow .15s}");
P.push("input[type=search]:focus,select:focus,.modal input:focus,.modal textarea:focus,.modal select:focus{outline:none;border-color:var(--blue-500);box-shadow:var(--shadow-glow)}");
P.push("input[type=search]{flex:1;min-width:190px}");
P.push(".statusline{font-size:12px;color:var(--slate-500);margin-left:auto;font-weight:600}");
P.push(".empty{text-align:center;padding:44px;color:var(--slate-400);font-size:13px}");
P.push("");
P.push("/* ---------- tables ---------- */");
P.push("table{width:100%;border-collapse:collapse;background:var(--white);border:1px solid var(--slate-200);border-radius:var(--radius-md);overflow:hidden;box-shadow:var(--shadow-sm)}");
P.push("th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--slate-100);vertical-align:top}");
P.push("th{background:var(--slate-50);font-size:10.5px;text-transform:uppercase;letter-spacing:.04em;color:var(--slate-500);font-weight:700;white-space:nowrap}");
P.push("tbody tr{transition:background .12s}");
P.push("tbody tr:hover{background:var(--slate-50)}");
P.push("tr:last-child td{border-bottom:none}");
P.push("td.name{font-weight:700;color:var(--slate-900)}");
P.push("#leadsView td.name,#crmView td.name{cursor:pointer;color:var(--blue-600)}");
P.push("#leadsView td.name:hover,#crmView td.name:hover{text-decoration:underline}");
P.push(".muted{color:var(--slate-400)}");
P.push("td.em{font-size:12.5px;word-break:break-all;font-family:var(--font-mono)}");
P.push("td.notes{font-size:12px;max-width:200px}");
P.push("td.na{font-size:12px;font-family:var(--font-mono);color:var(--slate-600)}");
P.push("");
P.push("/* ---------- pills / semantic badges ---------- */");
P.push(".pill{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:999px;font-size:10.5px;font-weight:700;white-space:nowrap;letter-spacing:.01em}");
P.push(".bd-hot{background:var(--red-100);color:var(--red-600)}");
P.push(".bd-warm{background:var(--amber-100);color:var(--amber-600)}");
P.push(".bd-cold{background:var(--teal-100);color:var(--teal-600)}");
P.push(".st-discovered{background:var(--indigo-100);color:var(--indigo-600)}");
P.push(".st-enriched{background:var(--green-100);color:var(--green-600)}");
P.push(".st-qualified{background:var(--amber-100);color:var(--amber-600)}");
P.push(".st-disqualified{background:var(--slate-100);color:var(--slate-500)}");
P.push(".st-default{background:var(--slate-100);color:var(--slate-600)}");
P.push(".dr-draft{background:var(--indigo-100);color:var(--indigo-600)}");
P.push(".dr-approved{background:var(--amber-100);color:var(--amber-600)}");
P.push(".dr-sent{background:var(--green-100);color:var(--green-600)}");
P.push(".stx-active{background:var(--green-100);color:var(--green-600)}");
P.push(".stx-won{background:var(--teal-100);color:var(--teal-600)}");
P.push(".stx-lost{background:var(--slate-100);color:var(--slate-500)}");
P.push(".stx-archived{background:var(--slate-100);color:var(--slate-400)}");
P.push(".bd-replied{background:var(--green-100);color:var(--green-600)}");
P.push(".bd-notcontacted{background:var(--slate-100);color:var(--slate-500)}");
P.push(".bd-awaitingfu{background:var(--amber-100);color:var(--amber-600)}");
P.push(".bd-proposal{background:var(--indigo-100);color:var(--indigo-600)}");
P.push(".stSel{padding:5px 8px;border:1px solid var(--slate-200);border-radius:var(--radius-sm);font-size:12px;background:var(--white);font-family:inherit}");
P.push("");
P.push("/* ---------- login ---------- */");
P.push(".login{display:flex;min-height:100vh;align-items:center;justify-content:center;padding:20px;background:var(--grad-sidebar);position:relative;overflow:hidden}");
P.push(".login::before{content:'';position:absolute;width:640px;height:640px;border-radius:50%;background:radial-gradient(circle,rgba(56,189,248,.18),transparent 70%);top:-220px;right:-220px}");
P.push(".login::after{content:'';position:absolute;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle,rgba(101,163,13,.14),transparent 70%);bottom:-200px;left:-180px}");
P.push(".lcard{position:relative;background:var(--white);border-radius:var(--radius-lg);padding:34px 32px;width:360px;display:flex;flex-direction:column;gap:12px;box-shadow:0 24px 64px rgba(2,6,23,.5);animation:lcardIn .5s var(--ease)}");
P.push("@keyframes lcardIn{from{opacity:0;transform:translateY(14px) scale(.98)}to{opacity:1;transform:none}}");
P.push(".lcard__logo{width:64px;height:64px;border-radius:16px;overflow:hidden;margin:0 auto 4px;display:flex;align-items:center;justify-content:center;background:var(--slate-50);box-shadow:var(--shadow-sm)}");
P.push(".lcard__logo img{width:64px;height:64px;object-fit:cover;border-radius:16px}");
P.push(".lcard h1{margin:0;font-size:19px;text-align:center}");
P.push(".lcard .lsub{color:var(--slate-500);font-size:12.5px;margin-bottom:4px;text-align:center}");
P.push(".lcard input{padding:11px 12px;border:1px solid var(--slate-200);border-radius:var(--radius-sm);font:inherit}");
P.push(".lcard button{padding:12px;border-radius:var(--radius-sm);border:none;background:var(--grad-brand);color:#fff;font-weight:700;cursor:pointer;font:inherit;transition:transform .15s var(--ease),box-shadow .15s var(--ease);box-shadow:0 6px 18px rgba(47,111,235,.35)}");
P.push(".lcard button:hover{transform:translateY(-1px);box-shadow:0 10px 24px rgba(47,111,235,.42)}");
P.push(".lcard button:active{transform:translateY(0) scale(.98)}");
P.push("#lErr{color:var(--red-600);font-size:12px;min-height:15px;text-align:center;font-weight:600}");
P.push("");
P.push("/* ---------- modals ---------- */");
P.push("#modalBg,#cModalBg{position:fixed;inset:0;background:rgba(10,14,30,.55);backdrop-filter:blur(3px);display:none;align-items:center;justify-content:center;padding:18px;z-index:50}");
P.push("#modalBg.open,#cModalBg.open{display:flex}");
P.push(".modal{background:var(--white);border-radius:var(--radius-lg);max-width:720px;width:100%;max-height:92vh;overflow:auto;padding:22px 24px;display:flex;flex-direction:column;gap:9px;box-shadow:var(--shadow-lg);animation:modalIn .22s var(--ease)}");
P.push("@keyframes modalIn{from{opacity:0;transform:translateY(10px) scale(.98)}to{opacity:1;transform:none}}");
P.push(".modal.wide{max-width:880px}");
P.push(".modal h2{margin:0;font-size:18px;font-weight:800;letter-spacing:-.01em}");
P.push(".modal label{font-size:10.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--slate-500);font-weight:700;margin-top:6px}");
P.push(".mbtns{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}");
P.push(".mbtns button{padding:10px 16px;border-radius:var(--radius-sm);border:1px solid var(--slate-200);background:var(--slate-50);cursor:pointer;font:inherit;font-weight:600;color:var(--slate-700);transition:all .15s var(--ease)}");
P.push(".mbtns button:hover{background:var(--slate-100);border-color:var(--slate-300)}");
P.push(".mbtns button.primary{background:var(--grad-brand);border-color:transparent;color:#fff;box-shadow:0 4px 14px rgba(47,111,235,.32)}");
P.push(".mbtns button.primary:hover{box-shadow:0 6px 18px rgba(47,111,235,.4)}");
P.push(".mbtns button:disabled{opacity:.5;cursor:not-allowed;transform:none;box-shadow:none}");
P.push("#mMsg{font-size:12px;color:var(--slate-600);min-height:15px;font-weight:600}");
P.push("#mMeta{font-size:12.5px;color:var(--slate-600)}");
P.push("#mProfile{font-size:12.5px;line-height:1.6;background:var(--slate-50);border:1px solid var(--slate-200);border-radius:var(--radius-sm);padding:10px 12px}");
P.push(".cgrid{display:grid;grid-template-columns:1fr 1fr;gap:4px 16px;font-size:12.5px;background:var(--slate-50);border:1px solid var(--slate-200);border-radius:var(--radius-sm);padding:12px 14px}");
P.push(".cgrid .k{color:var(--slate-500)}");
P.push(".cgrid .v{font-weight:700}");
P.push(".replyBox{background:var(--green-100);border:1px solid #A7F3D0;border-radius:var(--radius-sm);padding:9px 11px;font-size:12.5px;margin-top:6px}");
P.push(".saveHint{font-size:11px;color:var(--green-600);margin-left:6px;font-weight:600}");
P.push("");
P.push("/* ---------- timeline ---------- */");
P.push(".tlWrap{max-height:260px;overflow:auto;border:1px solid var(--slate-200);border-radius:var(--radius-sm);padding:4px 12px;background:var(--white)}");
P.push(".tlItem{border-left:2px solid var(--slate-200);margin-left:4px;padding:8px 0 8px 14px;position:relative}");
P.push(".tlItem:before{content:'';position:absolute;left:-5px;top:13px;width:8px;height:8px;border-radius:50%;background:var(--slate-400);box-shadow:0 0 0 3px var(--white)}");
P.push(".tlItem.k-reply:before{background:var(--green-500)}");
P.push(".tlItem.k-sent:before,.tlItem.k-followup:before{background:var(--blue-600)}");
P.push(".tlItem.k-stage_change:before{background:var(--amber-500)}");
P.push(".tlKind{font-size:10px;text-transform:uppercase;letter-spacing:.05em;font-weight:800;color:var(--slate-500)}");
P.push(".tlTs{font-size:11px;color:var(--slate-400);float:right;font-family:var(--font-mono)}");
P.push(".tlBody{font-size:12.5px;color:var(--slate-700);margin-top:3px;white-space:pre-wrap;line-height:1.5}");
P.push("");
P.push("/* ---------- ops center ---------- */");
P.push(".opsgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin-bottom:16px}");
P.push(".opscard{background:var(--white);border:1px solid var(--slate-200);border-radius:var(--radius-md);padding:14px 16px;box-shadow:var(--shadow-sm);transition:box-shadow .18s var(--ease)}");
P.push(".opscard:hover{box-shadow:var(--shadow-md)}");
P.push(".opscard h3{margin:0 0 9px;font-size:12.5px;text-transform:uppercase;letter-spacing:.04em;color:var(--slate-500);font-weight:800}");
P.push(".opscard .row{display:flex;justify-content:space-between;gap:10px;font-size:12.5px;padding:4px 0;border-bottom:1px solid var(--slate-100)}");
P.push(".opscard .row:last-child{border-bottom:none}");
P.push(".dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px;box-shadow:0 0 0 3px rgba(0,0,0,.03)}");
P.push(".dot-green{background:var(--green-500)}");
P.push(".dot-yellow{background:var(--amber-500)}");
P.push(".dot-red{background:var(--red-500)}");
P.push(".healthgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:9px;margin-bottom:16px}");
P.push(".healthitem{display:flex;align-items:center;justify-content:space-between;background:var(--white);border:1px solid var(--slate-200);border-radius:var(--radius-sm);padding:10px 12px;font-size:12.5px;text-transform:capitalize;font-weight:600}");
P.push(".notif-item{display:flex;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid var(--slate-100);font-size:12.5px;background:var(--white)}");
P.push(".notif-item.unread{background:var(--blue-100)}");
P.push(".notif-item:last-child{border-bottom:none}");
P.push(".notifBox{border:1px solid var(--slate-200);border-radius:var(--radius-md);overflow:hidden;box-shadow:var(--shadow-sm)}");
P.push(".sev-badge{padding:2px 8px;border-radius:999px;font-size:10px;font-weight:800;text-transform:uppercase}");
P.push(".sev-info{background:var(--teal-100);color:var(--teal-600)}");
P.push(".sev-warning{background:var(--amber-100);color:var(--amber-600)}");
P.push(".sev-error{background:var(--red-100);color:var(--red-600)}");
P.push(".notif-read-btn{font-size:11px;border:1px solid var(--slate-200);background:var(--white);border-radius:var(--radius-sm);padding:4px 9px;cursor:pointer;white-space:nowrap;height:fit-content;font-weight:600;font-family:inherit;transition:all .15s}");
P.push(".notif-read-btn:hover{background:var(--slate-100)}");
P.push(".markall{font-size:12px;border:1px solid var(--slate-200);background:var(--white);border-radius:var(--radius-sm);padding:7px 14px;cursor:pointer;font:inherit;font-weight:600;color:var(--slate-700);transition:all .15s var(--ease)}");
P.push(".markall:hover{background:var(--slate-100);border-color:var(--slate-300)}");
P.push(".opsh2{font-size:13.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--slate-500);font-weight:800;margin:26px 0 10px;display:flex;align-items:center;gap:8px}");
P.push(".opsh2:first-child{margin-top:0}");
P.push("</style></head><body>");
