P.push("<script>");
P.push("window.onerror=function(m){ try { var e=document.getElementById('lErr'); if(e) e.textContent='Page error: '+m; } catch(x){} return false; };");
P.push("var API='/webhook/worker-api-x9q2k4m7';");
P.push("var CTRL='/webhook/outreach-control-k3n8p';");
P.push("var TZ='Australia/Adelaide';");
P.push("function lsGet(k){ try { return localStorage.getItem(k)||''; } catch(e){ return ''; } }");
P.push("function lsSet(k,v){ try { localStorage.setItem(k,v); } catch(e){} }");
P.push("function lsDel(k){ try { localStorage.removeItem(k); } catch(e){} }");
P.push("var TK=lsGet('kq_tk');");
P.push("var DATA=[]; var CRM=[]; var CUR=null; var CCUR=null; var CRM_LOADED=false;");
P.push("var VIEW = (location.pathname.indexOf('crm-board') >= 0) ? 'crm' : 'leads';");
P.push("var STAGES=['discovered','enriched','qualified','disqualified','proposal_ready','outreach_active','appointment','lost','won'];");
P.push("var CSTAGES=['new','contacted','replied','meeting','quote_sent','negotiation','won','lost'];");
P.push("var CSTATUSES=['active','won','lost','archived'];");
P.push("var TL_KIND_LABEL={ discovered:'Discovered', qualified:'Qualified', sent:'Initial outreach sent', followup:'Follow-up sent', reply:'Reply received', stage_change:'Stage changed', notes:'Notes updated' };");
P.push("function esc(s){ return (s==null?'':String(s)).replace(/[&<>\"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]; }); }");
P.push("function bandOf(s){ return s==null?'cold':(Number(s)>=80?'hot':(Number(s)>=55?'warm':'cold')); }");
P.push("function el(id){ return document.getElementById(id); }");
P.push("function dt(s){ if(!s) return '-'; try { var d=new Date(s); return d.toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:TZ}); } catch(e){ return s; } }");
P.push("function dtt(s){ if(!s) return '-'; try { var d=new Date(s); return d.toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:TZ})+' '+d.toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit',timeZone:TZ}); } catch(e){ return s; } }");
P.push("function api(p){ p.token=TK; return fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}).then(function(r){ if(!r.ok) throw new Error('server error '+r.status); return r.json(); }); }");
P.push("function ctrl(p){ p.token=TK; return fetch(CTRL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}).then(function(r){ if(!r.ok) throw new Error('server error '+r.status); return r.json(); }); }");
P.push("function show(inApp){ el('loginWrap').style.display=inApp?'none':'flex'; el('appWrap').style.display=inApp?'block':'none'; }");
P.push("function setView(v){ VIEW=v; el('leadsView').style.display=v==='leads'?'block':'none'; el('crmView').style.display=v==='crm'?'block':'none'; el('opsView').style.display=v==='ops'?'block':'none'; el('tabLeads').className='tab'+(v==='leads'?' active':''); el('tabCrm').className='tab'+(v==='crm'?' active':''); el('tabOps').className='tab'+(v==='ops'?' active':''); if(v==='crm') loadCrm(); if(v==='ops') loadOps(); }");
P.push("function doLogin(ev){ if(ev&&ev.preventDefault) ev.preventDefault(); el('lErr').textContent='Signing in...'; api({action:'login',name:el('lName').value.trim(),password:el('lPass').value}).then(function(j){ if(j.ok){ TK=j.token; lsSet('kq_tk',TK); el('lErr').textContent=''; boot(); } else { el('lErr').textContent=j.error||'login failed'; } }).catch(function(e){ el('lErr').textContent='Could not reach server: '+e.message; }); return false; }");
P.push("function boot(){ if(!TK){ show(false); return; } api({action:'leads'}).then(function(j){ if(j.ok){ DATA=j.leads; show(true); fill(); render(); setView(VIEW); } else { TK=''; lsDel('kq_tk'); show(false); } }).catch(function(e){ show(false); el('lErr').textContent='Could not load leads: '+e.message; }); }");
P.push("function loadCrm(){ api({action:'crm_list'}).then(function(j){ if(j.ok){ CRM=j.records; if(!CRM_LOADED){ cfill(); CRM_LOADED=true; } crender(); } }).catch(function(e){ el('ctableWrap').innerHTML='<div class=\"empty\">Could not load CRM: '+esc(e.message)+'</div>'; }); }");
P.push("function fill(){ var subs={}; DATA.forEach(function(r){ if(r.suburb) subs[r.suburb]=1; }); var fs=el('fSuburb'); while(fs.options.length>1) fs.remove(1); Object.keys(subs).sort().forEach(function(s){ var o=document.createElement('option'); o.value=s; o.textContent=s; fs.appendChild(o); }); var fg=el('fStage'); while(fg.options.length>1) fg.remove(1); STAGES.forEach(function(s){ var o=document.createElement('option'); o.value=s; o.textContent=s; fg.appendChild(o); }); }");
P.push("function cfill(){ var fs=el('cfStage'); CSTAGES.forEach(function(s){ var o=document.createElement('option'); o.value=s; o.textContent=s.replace('_',' '); fs.appendChild(o); }); var fx=el('cfStatus'); CSTATUSES.forEach(function(s){ var o=document.createElement('option'); o.value=s; o.textContent=s; fx.appendChild(o); }); var segs={}; CRM.forEach(function(r){ if(r.segment) segs[r.segment]=1; }); var fseg=el('cfSegment'); while(fseg.options.length>1) fseg.remove(1); Object.keys(segs).sort().forEach(function(s){ var o=document.createElement('option'); o.value=s; o.textContent=s; fseg.appendChild(o); }); var cstageSelOpts=CSTAGES.map(function(s){ return '<option value=\"'+s+'\">'+s.replace('_',' ')+'</option>'; }).join(''); el('cStageSel').innerHTML=cstageSelOpts; }");
P.push("function filtered(){ var q=el('q').value.trim().toLowerCase(); var sub=el('fSuburb').value; var stg=el('fStage').value; var bd=el('fBand').value; var fd=el('fDraft').value; return DATA.filter(function(r){ if (sub && r.suburb!==sub) return false; if (stg && r.stage!==stg) return false; if (bd && bandOf(r.qualification_score)!==bd) return false; if (fd && (r.draft_status||'')!==fd) return false; if (q){ var hay=[r.business_name,r.address,r.suburb,r.phone,r.email,r.segment,r.description].map(function(x){return (x||'').toLowerCase();}).join(' '); if (hay.indexOf(q)===-1) return false; } return true; }); }");
P.push("function quickMatch(r,quick){ if(!quick) return true; if(quick==='replied') return r.stage==='replied' || !!r.last_reply_at; if(quick==='not_contacted') return r.stage==='new'; if(quick==='awaiting_followup') return !!r.next_followup_at; if(quick==='proposal_sent') return r.stage==='quote_sent'; return true; }");
P.push("function cfiltered(){ var q=el('cq').value.trim().toLowerCase(); var st=el('cfStage').value; var sx=el('cfStatus').value; var so=el('cfSource').value; var seg=el('cfSegment').value; var bd=el('cfBand').value; var quick=el('cfQuick').value; return CRM.filter(function(r){ if (st && r.stage!==st) return false; if (sx && r.status!==sx) return false; if (so && r.source!==so) return false; if (seg && r.segment!==seg) return false; if (bd && bandOf(r.qualification_score)!==bd) return false; if (!quickMatch(r,quick)) return false; if (q){ var hay=[r.business_name,r.suburb,r.address,r.owner,r.notes,r.next_action,r.segment].map(function(x){return (x||'').toLowerCase();}).join(' '); if (hay.indexOf(q)===-1) return false; } return true; }); }");
P.push("function stats(list){ var c={hot:0,warm:0,cold:0,sent:0}; list.forEach(function(r){ c[bandOf(r.qualification_score)]++; if(r.draft_status==='sent') c.sent++; }); var cards=[['Leads',list.length],['Hot',c.hot],['Warm',c.warm],['Cold',c.cold],['Sent',c.sent]]; el('stats').innerHTML = cards.map(function(a){ return '<div class=\"stat\"><div class=\"n\">'+a[1]+'</div><div class=\"l\">'+a[0]+'</div></div>'; }).join(''); }");
P.push("function cstatsFn(list){ var byStage={}; var fuActive=0; var replied=0; list.forEach(function(r){ byStage[r.stage]=(byStage[r.stage]||0)+1; if(r.next_followup_at) fuActive++; if(r.stage==='replied'||r.last_reply_at) replied++; }); var cards=[['In CRM',list.length],['Contacted',byStage['contacted']||0],['Replied',replied],['Meetings',byStage['meeting']||0],['Follow-ups active',fuActive],['Won',byStage['won']||0]]; el('cstats').innerHTML = cards.map(function(a){ return '<div class=\"stat\"><div class=\"n\">'+a[1]+'</div><div class=\"l\">'+a[0]+'</div></div>'; }).join(''); }");
P.push("function fuCell(r){ if(!r.sent_at) return '<span class=\"muted\">-</span>'; var n=Number(r.followup_count||0); if(n>=3) return '<span class=\"pill dr-sent\">3 of 3 done</span>'; if(r.stage!=='contacted'||r.status!=='active') return n>0?('<span class=\"muted\">stopped after '+n+'</span>'):'<span class=\"muted\">not needed</span>'; return '<span class=\"pill dr-approved\">'+n+' of 3</span><div class=\"muted\" style=\"font-size:11px\">next '+dt(r.next_followup_at)+'</div>'; }");
P.push("function replyBadge(r){ if(r.stage!=='replied' && !r.last_reply_at) return ''; return '<span class=\"pill bd-replied\" title=\"'+esc(r.last_reply_subject||'')+'\">Replied '+(r.last_reply_at?dt(r.last_reply_at):'')+'</span>'; }");
P.push("function render(){ var list=filtered(); stats(list); el('status').textContent = list.length+' shown / '+DATA.length; if (!list.length){ el('tableWrap').innerHTML='<div class=\"empty\">No leads match.</div>'; return; } var html='<table><thead><tr><th>#</th><th>Business</th><th>Address</th><th>Phone</th><th>Email</th><th>Band</th><th>Status</th><th>Draft</th></tr></thead><tbody>'; html += list.map(function(r, i){ var b=bandOf(r.qualification_score); var sc=STAGES.indexOf(r.stage)>=0?('st-'+r.stage):'st-default'; var ds=r.draft_status?('<span class=\"pill dr-'+esc(r.draft_status)+'\">'+esc(r.draft_status)+'</span>'):'<span class=\"muted\">-</span>'; var em=r.email?('<a href=\"mailto:'+esc(r.email)+'\">'+esc(r.email)+'</a>'):'<span class=\"muted\">-</span>'; return '<tr data-eid=\"'+r.id+'\"><td class=\"muted\">'+(i+1)+'</td><td class=\"name\">'+esc(r.business_name)+(r.suburb?('<div class=\"muted\" style=\"font-weight:400;font-size:12px\">'+esc(r.suburb)+'</div>'):'')+'</td><td>'+esc(r.address||'')+'</td><td>'+(r.phone?('<a href=\"tel:'+esc(r.phone)+'\">'+esc(r.phone)+'</a>'):'<span class=\"muted\">-</span>')+'</td><td class=\"em\">'+em+'</td><td><span class=\"pill bd-'+b+'\">'+b+'</span></td><td><span class=\"pill '+sc+'\">'+esc(r.stage)+'</span></td><td>'+ds+'</td></tr>'; }).join(''); html += '</tbody></table>'; el('tableWrap').innerHTML = html; Array.prototype.forEach.call(document.querySelectorAll('#leadsView tr[data-eid] td.name'), function(td){ td.onclick=function(){ openLead(td.parentNode.getAttribute('data-eid')); }; }); }");
P.push("function crender(){ var list=cfiltered(); cstatsFn(list); el('cstatus').textContent = list.length+' shown / '+CRM.length; if (!list.length){ el('ctableWrap').innerHTML='<div class=\"empty\">No CRM records match. Send an email or use Add to CRM on the Lead Board.</div>'; return; } var html='<table><thead><tr><th>Business</th><th>Segment</th><th>Contact</th><th>Owner</th><th>Status</th><th>Stage</th><th>Reply</th><th>Follow-ups</th><th>Last contact</th><th>Next action</th><th>Notes</th></tr></thead><tbody>'; html += list.map(function(r){ var contact=[]; if(r.phone) contact.push('<a href=\"tel:'+esc(r.phone)+'\">'+esc(r.phone)+'</a>'); if(r.email) contact.push('<a href=\"mailto:'+esc(r.email)+'\">'+esc(r.email)+'</a>'); if(r.website) contact.push('<a href=\"'+esc(r.website)+'\" target=\"_blank\" rel=\"noopener\">site</a>'); var na=r.next_action?esc(r.next_action)+(r.next_action_due?(' <span class=\"muted\">(due '+esc(r.next_action_due)+')</span>'):''):'<span class=\"muted\">-</span>'; var notes=r.notes?esc(r.notes.length>90?(r.notes.slice(0,90)+'...'):r.notes):'<span class=\"muted\">-</span>'; var stageSel='<select class=\"stSel\" data-cid=\"'+esc(String(r.candidate_id))+'\">'+CSTAGES.map(function(s){ return '<option value=\"'+s+'\"'+(s===r.stage?' selected':'')+'>'+s.replace('_',' ')+'</option>'; }).join('')+'</select>'; return '<tr data-cid=\"'+esc(String(r.candidate_id))+'\"><td class=\"name\">'+esc(r.business_name)+(r.suburb?('<div class=\"muted\" style=\"font-weight:400;font-size:12px\">'+esc(r.suburb)+'</div>'):'')+'</td><td style=\"font-size:12px\">'+esc(r.segment||'-')+'</td><td style=\"font-size:12px\">'+(contact.join('<br>')||'-')+'</td><td>'+esc(r.owner||'-')+'</td><td><span class=\"pill stx-'+esc(r.status)+'\">'+esc(r.status)+'</span></td><td>'+stageSel+'</td><td>'+(replyBadge(r)||'<span class=\"muted\">-</span>')+'</td><td>'+fuCell(r)+'</td><td class=\"na\">'+dtt(r.last_contact_at)+'</td><td class=\"na\">'+na+'</td><td class=\"notes\">'+notes+'</td></tr>'; }).join(''); html += '</tbody></table>'; el('ctableWrap').innerHTML = html;");
P.push("  Array.prototype.forEach.call(document.querySelectorAll('#crmView tr[data-cid] td.name'), function(td){ td.onclick=function(){ openCrmProfile(td.parentNode.getAttribute('data-cid')); }; });");
P.push("  Array.prototype.forEach.call(document.querySelectorAll('.stSel'), function(sel){ sel.onchange=function(){ var cid=sel.getAttribute('data-cid'); sel.disabled=true; api({action:'crm_stage',candidate_id:cid,stage:sel.value}).then(function(j){ if(j.ok){ loadCrm(); } else { alert('Could not update stage'); sel.disabled=false; } }).catch(function(e){ alert('Stage update failed: '+e.message); sel.disabled=false; }); }; });");
