const OPEN_OLD = 'el(\'cModalBg\').style.display=\'flex\'; loadTimeline(CCUR.candidate_id);';
const OPEN_NEW = OPEN_OLD + ' loadConversation(CCUR.candidate_id);';
const BOX = '<div id="cReplyBox"></div>';

let html = String($json.html || '');
const before = html.length;
const applied = [];

function inject(needle, replacement, label) {
  if (html.indexOf(needle) === -1) { applied.push(label + ':MISSING'); return; }
  html = html.split(needle).join(replacement);
  applied.push(label + ':ok');
}

